import fs from 'fs';
import path from 'path';
import { log } from '../../core/logger.js';
import { escapeXml } from '../utils.js';
export function writeStringsXml(config, directory) {
    fs.mkdirSync(directory, { recursive: true });
    fs.writeFileSync(path.join(directory, 'strings.xml'), `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <string name="app_name">${escapeXml(config.appName)}</string>
</resources>`);
    log.dim('  strings.xml');
}
export function writeStylesXml(config, directory) {
    fs.mkdirSync(directory, { recursive: true });
    const parent = config.statusBar === 'dark' ? 'Theme.AppCompat.NoActionBar' : 'Theme.AppCompat.Light.NoActionBar';
    fs.writeFileSync(path.join(directory, 'styles.xml'), `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <style name="AppTheme" parent="${parent}">
        <item name="colorPrimary">@color/colorPrimary</item>
        <item name="colorPrimaryDark">@color/colorPrimaryDark</item>
        <item name="colorAccent">@color/colorAccent</item>
        <item name="android:windowBackground">@color/windowBackground</item>
        <item name="android:statusBarColor">@color/colorPrimaryDark</item>
    </style>
</resources>`);
    log.dim('  styles.xml');
}
export function writeColorsXml(config, directory) {
    fs.mkdirSync(directory, { recursive: true });
    fs.writeFileSync(path.join(directory, 'colors.xml'), `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="colorPrimary">${config.themeColor ?? '#FFFFFF'}</color>
    <color name="colorPrimaryDark">${config.themeColor ?? '#FFFFFF'}</color>
    <color name="colorAccent">${config.themeColor ?? '#2196F3'}</color>
    <color name="windowBackground">${config.backgroundColor ?? '#FFFFFF'}</color>
</resources>`);
    log.dim('  colors.xml');
}
export function writeNetworkSecurityConfig(config, resDirectory) {
    if (!config.clearTextDomains?.length && !config.allowAllClearText)
        return;
    const xmlDirectory = path.join(resDirectory, 'xml');
    fs.mkdirSync(xmlDirectory, { recursive: true });
    const body = config.allowAllClearText ? `    <base-config cleartextTrafficPermitted="true" />` : config.clearTextDomains.map(domain => `    <domain-config cleartextTrafficPermitted="true">
        <domain includeSubdomains="true">${escapeXml(domain)}</domain>
    </domain-config>`).join('\n');
    fs.writeFileSync(path.join(xmlDirectory, 'network_security_config.xml'), `<?xml version="1.0" encoding="utf-8"?>
<network-security-config>
${body}
</network-security-config>`);
    log.dim('  network_security_config.xml');
}
